class Solution {
  singleNonDuplicate(nums) {
    const n = nums.length;
    let low = 0,
      high = n - 1;
    while (low <= high) {
      const mid = Math.floor((low + high) / 2);
      let onLeft = nums[mid] === nums[mid - 1];
      let onRight = nums[mid] === nums[mid + 1];
      if (onLeft) {
        const goRight = (mid - low) % 2 === 1;
        if (goRight) {
          low = mid + 1;
        } else {
          high = mid - 2;
        }
      } else if (onRight) {
        const goRight = (mid - low) % 2 === 0;
        if (goRight) {
          low = mid + 2;
        } else {
          high = mid - 1;
        }
      } else {
        return nums[mid];
      }
    }
  }
}

