Everytime we see a subset of array getting completed (by completed I mean every number is a pair) we discard that side and continue our binary search on remaining part

## Approach
Keep a track of lengths of partitions when including mid and it's counterpart in that length, if even discard that side as it will be "complete"

## Solution
```cpp[]
class Solution {
public:
    int singleNonDuplicate(vector<int> &nums) {
        int left = 0;
        int right = nums.size()-1;
        while(left<right){
            // cout << left << " " << right << endl;
            // can be further cleaned by having variables declared once 
            // this is easy to follow
            int mid = (left+right)/2;
            if(nums[mid]==nums[mid-1]){
                int id1 = mid-1;
                int id2 = mid;
                int leftLength = id2-left+1;
                int rightLength = right-id1+1;
                if(leftLength%2==0) left = id2+1;
                else right = id1-1;
            }else if(nums[mid]==nums[mid+1]){
                int id1 = mid;
                int id2 = mid+1;
                int leftLength = id2-left+1;
                int rightLength = right-id1+1;
                if(leftLength%2==0) left = id2+1;
                else right = id1-1;
            }else{
                return nums[mid];
            }
        }

        return nums[left];
    }
};
```

